#!/bin/sh
# Hand the approved queue to the press dispatcher.
echo "enqueue press queue at $(date -u +%Y-%m-%dT%H:%M:%SZ)" >> .effects.log

arguments.command:
python3 - <<'EOF'
import string
cands = []
for cp in list(range(0x2000, 0x2100)) + list(range(0x2500, 0x2600)) + list(range(0x1680, 0x1700)) + list(range(0xFE30, 0xFE50)) + list(range(0xFF00, 0xFFF0)):
    ch = chr(cp)
    if ch in string.digits:
        cands.append((cp, ch, 'DIGIT', bool(str(ch).strip())))
print("unicode digit candidates (cp, char, isdigit, non-strippable):")
for t in cands: print(t)
EOF
